<script setup lang="ts">
/**
 * Staff help browser — index, view, DB override edit/create/delete.
 */
import { computed, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { api } from "@/api/client";
import type { HelpEntry, HelpIndex } from "@/api/types";
import { useFormSync } from "@/composables/useFormSync";

const props = defineProps<{ topic?: string }>();
const route = useRoute();
const router = useRouter();

const topics = ref<HelpEntry[]>([]);
const sections = ref<string[]>([]);
const selected = ref<HelpEntry | null>(null);
const q = ref("");
const sectionFilter = ref("all");
const sourceFilter = ref("all");
const loadError = ref("");
const saveError = ref("");
const saveOk = ref("");
const busy = ref(false);
const loading = ref(false);
const editing = ref(false);
const creating = ref(false);

const newName = ref("");
const {
  form,
  dirty,
  markSaved,
  resetFrom,
  confirmLeave,
} = useFormSync(selected, (e) => ({
  content: e.content || "",
  section: e.section || "general",
  tags: (e.tags || []).join(", "),
}));

const filtered = computed(() => {
  let list = [...topics.value];
  if (sectionFilter.value !== "all") {
    list = list.filter((t) => t.section === sectionFilter.value);
  }
  if (sourceFilter.value !== "all") {
    list = list.filter((t) => t.source === sourceFilter.value);
  }
  const n = q.value.trim().toLowerCase();
  if (n) {
    list = list.filter((t) =>
      `${t.name} ${t.section} ${t.tags?.join(" ") || ""} ${
        t.content?.slice(0, 200) || ""
      }`.toLowerCase().includes(n)
    );
  }
  return list.sort((a, b) => a.name.localeCompare(b.name));
});

const statsLine = computed(() => {
  const total = topics.value.length;
  const db = topics.value.filter((t) => t.source === "database")
    .length;
  const file = topics.value.filter((t) => t.source === "file")
    .length;
  const cmd = topics.value.filter((t) => t.source === "command")
    .length;
  return `${total} topics · ${file} file · ${cmd} command · ${db} DB`;
});

function topicPath(name: string): string {
  return name.split("/").map(encodeURIComponent).join("/");
}

async function loadIndex(): Promise<void> {
  loading.value = true;
  loadError.value = "";
  try {
    const { res, data } = await api<HelpIndex & { error?: string }>(
      "/api/v1/help",
    );
    if (!res.ok) {
      loadError.value = data?.error ||
        `Load failed (${res.status})`;
      topics.value = [];
      sections.value = [];
      return;
    }
    topics.value = data?.topics ?? [];
    sections.value = data?.sections ?? [];
  } finally {
    loading.value = false;
  }
}

async function openTopic(name: string): Promise<void> {
  if (
    editing.value && dirty.value &&
    !confirmLeave("Discard unsaved help changes?")
  ) {
    return;
  }
  loadError.value = "";
  saveOk.value = "";
  creating.value = false;
  editing.value = false;
  const path = `/api/v1/help/${topicPath(name)}`;
  const { res, data } = await api<
    { entry?: HelpEntry; error?: string }
  >(path);
  if (!res.ok || !data?.entry) {
    loadError.value = data?.error ||
      `Open failed (${res.status})`;
    return;
  }
  selected.value = data.entry;
  markSaved();
  const enc = topicPath(name);
  if (props.topic !== name) {
    await router.replace({
      name: "help-detail",
      params: { topic: enc },
    });
  }
}

function clearSelection(): void {
  if (
    editing.value && dirty.value &&
    !confirmLeave("Discard unsaved help changes?")
  ) {
    return;
  }
  selected.value = null;
  editing.value = false;
  creating.value = false;
  void router.replace({ name: "help" });
}

function startCreate(): void {
  if (
    editing.value && dirty.value &&
    !confirmLeave("Discard unsaved help changes?")
  ) {
    return;
  }
  selected.value = null;
  creating.value = true;
  editing.value = true;
  newName.value = "";
  selected.value = {
    name: "",
    section: "general",
    content: "",
    source: "database",
    tags: [],
  };
  markSaved();
  void router.replace({ name: "help", query: { new: "1" } });
}

function startEdit(): void {
  if (!selected.value) return;
  editing.value = true;
  markSaved();
}

async function save(): Promise<void> {
  if (!form.value) return;
  saveError.value = "";
  const name = creating.value
    ? newName.value.trim().toLowerCase().replace(/\s+/g, "-")
    : selected.value?.name;
  if (!name) {
    saveError.value = "Topic name is required.";
    return;
  }
  if (!form.value.content.trim()) {
    saveError.value = "Content is required.";
    return;
  }
  busy.value = true;
  try {
    const tags = form.value.tags
      .split(/[,;\s]+/)
      .map((t) => t.trim())
      .filter(Boolean);
    const path = `/api/v1/help/${topicPath(name)}`;
    const { res, data } = await api<
      { entry?: HelpEntry; error?: string }
    >(path, {
      method: "POST",
      body: JSON.stringify({
        content: form.value.content,
        section: form.value.section.trim() || "general",
        tags,
      }),
    });
    if (!res.ok) {
      saveError.value = data?.error ||
        `Save failed (${res.status})`;
      return;
    }
    creating.value = false;
    editing.value = false;
    saveOk.value = selected.value?.source === "database" ||
        data?.entry?.source === "database"
      ? "Saved database override."
      : "Saved.";
    await loadIndex();
    if (data?.entry) {
      selected.value = data.entry;
      markSaved();
      await router.replace({
        name: "help-detail",
        params: { topic: topicPath(data.entry.name) },
      });
    }
  } finally {
    busy.value = false;
  }
}

async function removeOverride(): Promise<void> {
  if (!selected.value || selected.value.source !== "database") {
    return;
  }
  if (
    !confirm(
      `Delete database override for “${selected.value.name}”? ` +
        `File/command help (if any) will show again.`,
    )
  ) {
    return;
  }
  busy.value = true;
  saveError.value = "";
  try {
    const path = `/api/v1/help/${topicPath(selected.value.name)}`;
    const { res, data } = await api<{ error?: string }>(path, {
      method: "DELETE",
    });
    if (!res.ok && res.status !== 204) {
      saveError.value = data?.error ||
        `Delete failed (${res.status})`;
      return;
    }
    selected.value = null;
    editing.value = false;
    saveOk.value = "Override removed.";
    await loadIndex();
    void router.replace({ name: "help" });
  } finally {
    busy.value = false;
  }
}

function sourceClass(src: string): string {
  if (src === "database") return "badge-db";
  if (src === "file") return "badge-file";
  if (src === "command") return "badge-cmd";
  return "";
}

watch(
  () => props.topic,
  (t) => {
    if (t) {
      const name = decodeURIComponent(String(t));
      void openTopic(name);
    } else if (route.query.new !== "1") {
      selected.value = null;
      creating.value = false;
      editing.value = false;
    }
  },
  { immediate: true },
);

watch(
  () => route.query.new,
  (n) => {
    if (n === "1" && !creating.value) startCreate();
  },
);

onMounted(() => {
  void loadIndex();
});

const showList = computed(
  () => !selected.value && !creating.value,
);
</script>

<template>
  <article
    v-if="showList"
    id="main-help"
    class="dash-browser"
  >
    <header class="dash-header">
      <div>
        <h1 class="page-title">
          Help
        </h1>
        <p class="muted lede">
          {{ statsLine }}
        </p>
      </div>
      <div class="dash-header-actions">
        <button
          type="button"
          class="secondary outline"
          :disabled="loading"
          @click="loadIndex"
        >
          Refresh
        </button>
        <button
          type="button"
          @click="startCreate"
        >
          New override
        </button>
      </div>
    </header>

    <section
      class="pages-toolbar help-toolbar"
      aria-label="Filter help"
    >
      <label class="pages-search-label">
        <span class="sr-only">Search</span>
        <input
          v-model="q"
          type="search"
          placeholder="Search topic, section, tags…"
          autocomplete="off"
        >
      </label>
      <label class="filter-select">
        <span class="sr-only">Section</span>
        <select v-model="sectionFilter">
          <option value="all">
            All sections
          </option>
          <option
            v-for="s in sections"
            :key="s"
            :value="s"
          >
            {{ s }}
          </option>
        </select>
      </label>
      <label class="filter-select">
        <span class="sr-only">Source</span>
        <select v-model="sourceFilter">
          <option value="all">
            All sources
          </option>
          <option value="file">
            file
          </option>
          <option value="command">
            command
          </option>
          <option value="database">
            database
          </option>
        </select>
      </label>
    </section>

    <p
      v-if="loadError"
      class="error"
      role="alert"
    >
      {{ loadError }}
    </p>
    <p
      v-if="saveOk"
      class="muted"
    >
      {{ saveOk }}
    </p>

    <div class="table-wrap">
      <table class="dash-table">
        <thead>
          <tr>
            <th scope="col">
              Topic
            </th>
            <th scope="col">
              Section
            </th>
            <th scope="col">
              Source
            </th>
            <th scope="col">
              Tags
            </th>
            <th scope="col">
              <span class="sr-only">Open</span>
            </th>
          </tr>
        </thead>
        <tbody>
          <tr v-if="loading">
            <td
              colspan="5"
              class="muted"
            >
              Loading…
            </td>
          </tr>
          <tr v-else-if="!filtered.length">
            <td
              colspan="5"
              class="muted"
            >
              No topics match.
            </td>
          </tr>
          <tr
            v-for="t in filtered"
            :key="t.name"
            tabindex="0"
            @click="openTopic(t.name)"
            @keydown.enter.prevent="openTopic(t.name)"
          >
            <td>
              <code>{{ t.name }}</code>
              <span
                v-if="t.hidden"
                class="badge muted-badge"
              >hidden</span>
            </td>
            <td class="muted">
              {{ t.section }}
            </td>
            <td>
              <span
                class="badge"
                :class="sourceClass(t.source)"
              >{{ t.source }}</span>
            </td>
            <td class="muted">
              {{ (t.tags || []).join(", ") || "—" }}
            </td>
            <td class="row-open">
              <button
                type="button"
                class="secondary outline"
                @click.stop="openTopic(t.name)"
              >
                Open
              </button>
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  </article>

  <!-- Detail / edit / create -->
  <article
    v-else-if="selected && form"
    id="main-help-detail"
    class="dash-browser"
  >
    <header class="editor-header">
      <div>
        <p class="editor-path-line">
          <button
            type="button"
            class="back-link"
            @click="clearSelection"
          >
            ← Help
          </button>
          <span
            v-if="!creating"
            class="badge"
            :class="sourceClass(selected.source)"
          >{{ selected.source }}</span>
          <span
            v-if="dirty"
            class="dirty-dot"
            title="Unsaved"
          >●</span>
          <small
            v-if="saveOk"
            class="muted"
          >{{ saveOk }}</small>
        </p>
        <h1 class="page-title page-title-tight">
          <template v-if="creating">
            New DB override
          </template>
          <template v-else>
            {{ selected.name }}
          </template>
        </h1>
        <p
          v-if="!creating"
          class="muted jobs-detail-meta"
        >
          section {{ selected.section }}
          <template v-if="selected.tags?.length">
            · {{ selected.tags.join(", ") }}
          </template>
        </p>
      </div>
      <div class="editor-actions">
        <template v-if="editing">
          <button
            type="button"
            class="secondary outline"
            :disabled="busy"
            @click="creating ? clearSelection() : (
              editing = false,
              selected && resetFrom(selected)
            )"
          >
            Cancel
          </button>
          <button
            type="button"
            :disabled="busy || (!dirty && !creating)"
            @click="save"
          >
            {{ creating ? "Create" : "Save override" }}
          </button>
        </template>
        <template v-else>
          <button
            type="button"
            class="secondary"
            :disabled="busy"
            @click="startEdit"
          >
            {{
              selected.source === "database"
                ? "Edit"
                : "Override"
            }}
          </button>
          <button
            v-if="selected.source === 'database'"
            type="button"
            class="secondary outline"
            :disabled="busy"
            @click="removeOverride"
          >
            Delete override
          </button>
        </template>
      </div>
    </header>

    <p
      v-if="loadError || saveError"
      class="error"
      role="alert"
    >
      {{ loadError || saveError }}
    </p>

    <p
      v-if="!editing && selected.source !== 'database'"
      class="muted help-hint"
    >
      This topic comes from
      <strong>{{ selected.source }}</strong>.
      Saving an override stores a database copy that wins
      over file/command help.
    </p>

    <form
      v-if="editing"
      @submit.prevent="save"
    >
      <label v-if="creating">
        Topic name
        <input
          v-model="newName"
          required
          placeholder="mail/send or my-topic"
          pattern="[a-z0-9][a-z0-9\-/]*"
        >
      </label>
      <div class="db-edit-grid">
        <label>
          Section
          <input v-model="form.section">
        </label>
        <label>
          Tags (comma-separated)
          <input v-model="form.tags">
        </label>
      </div>
      <label>
        Content (markdown)
        <textarea
          v-model="form.content"
          rows="18"
          class="help-editor"
          required
        />
      </label>
    </form>

    <pre
      v-else
      class="help-body"
    >{{ selected.content || "(empty)" }}</pre>
  </article>
</template>

<style scoped>
.help-toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
}
.filter-select select {
  min-height: 2.35rem;
  margin: 0;
}
.badge-db {
  background: color-mix(in srgb, var(--pico-primary, #7c5cbf) 25%, transparent);
}
.badge-file {
  background: color-mix(in srgb, #3d8 18%, transparent);
}
.badge-cmd {
  background: color-mix(in srgb, #48f 18%, transparent);
}
.muted-badge {
  margin-left: 0.35rem;
  font-size: 0.7rem;
  opacity: 0.85;
}
.help-body {
  white-space: pre-wrap;
  word-break: break-word;
  margin: 1rem 0 0;
  padding: 1rem 1.15rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  font: inherit;
  line-height: 1.5;
  max-width: 52rem;
}
.help-editor {
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 0.875rem;
  line-height: 1.45;
}
.help-hint {
  margin: 0.5rem 0 1rem;
  max-width: 40rem;
}
</style>
